COPILOT_DOCKERFILE = 'FROM node:22-bookworm\n\n# Install system dependencies\nRUN apt-get update && apt-get install -y \\\n  git \\\n  curl \\\n  jq \\\n  && rm -rf /var/lib/apt/lists/*\n\n{{ISSUE_TRACKER_TOOLS}}\n\n# Build-args for UID/GID alignment: sandcastle docker build-image\n# defaults these to the host user\'s UID/GID so image-built files\n# and bind-mounted files share an owner without runtime chown.\nARG AGENT_UID=1000\nARG AGENT_GID=1000\n\n# Rename the base image\'s "node" user to "agent" and align UID/GID.\nRUN groupmod -o -g $AGENT_GID node && usermod -o -u $AGENT_UID -g $AGENT_GID -d /home/agent -m -l agent node\n\n# Install GitHub Copilot CLI (run as root before USER agent)\nRUN npm install -g @github/copilot\n\nUSER ${AGENT_UID}:${AGENT_GID}\n\nWORKDIR /home/agent\n\n# In worktree sandbox mode, Sandcastle bind-mounts the git worktree at /home/agent/workspace\n# and overrides the working directory to /home/agent/workspace at container start.\n# Structure your Dockerfile so that /home/agent/workspace can serve as the project root.\nENTRYPOINT ["sleep", "infinity"]\n'
GITHUB_CLI_TOOLS = '# Install GitHub CLI\nRUN curl -fsSL https://cli.github.com/packages/githubcli-archive-keyring.gpg \\\n  | dd of=/usr/share/keyrings/githubcli-archive-keyring.gpg \\\n  && echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/githubcli-archive-keyring.gpg] https://cli.github.com/packages stable main" \\\n  | tee /etc/apt/sources.list.d/github-cli.list > /dev/null \\\n  && apt-get update && apt-get install -y gh \\\n  && rm -rf /var/lib/apt/lists/*'
BEADS_TOOLS = '# Install system dependencies for Beads\nRUN apt-get update && apt-get install -y \\\n  dpkg-dev \\\n  libicu72 \\\n  && rm -rf /var/lib/apt/lists/* \\\n  && ARCH_DIR=$(dpkg-architecture -qDEB_HOST_MULTIARCH) \\\n  && for lib in /usr/lib/$ARCH_DIR/libicu*.so.72; do \\\n       ln -s "$lib" "${lib%.72}.74"; \\\n     done\n\n# Pinned bd release. Every sandbox opens your host\'s beads database (see\n# sandboxOptions in main), so keep this equal to the host\'s `bd version`.\nARG BEADS_VERSION=1.3.2\nRUN ARCH=$(dpkg --print-architecture) \\\n  && BEADS_TARBALL="beads_${BEADS_VERSION}_linux_${ARCH}.tar.gz" \\\n  && BEADS_URL="https://github.com/gastownhall/beads/releases/download/v${BEADS_VERSION}" \\\n  && cd /tmp \\\n  && curl -fsSLO "${BEADS_URL}/${BEADS_TARBALL}" \\\n  && curl -fsSL "${BEADS_URL}/checksums.txt" | grep " ${BEADS_TARBALL}$" | sha256sum -c - \\\n  && tar -xzf "${BEADS_TARBALL}" -C /usr/local/bin bd \\\n  && rm "${BEADS_TARBALL}" \\\n  && bd version\n\nRUN corepack enable'
BEADS_SANDBOX_OPTIONS = '// Beads keeps its database in .beads/, which git ignores, so a worktree\n// sandbox never gets it. Mount the host\'s .beads/ into every sandbox and point\n// bd at it, so every phase reads and closes issues in the one shared database.\n// Run this file from the repo root (hostPath is relative to the cwd).\nconst sandboxOptions = {\n  mounts: [{ hostPath: ".beads", sandboxPath: "/home/agent/host-beads" }],\n  env: { BEADS_DIR: "/home/agent/host-beads" },\n};'
BEADS_NATIVE_SANDBOX_OPTIONS = "// Beads keeps its database in .beads/, which git ignores, so a worktree\n// sandbox never gets it. Mount the host's .beads/ into every sandbox, at its\n// own path, and point bd at it, so every phase reads and closes issues in the\n// one shared database. Run this file from the repo root.\nconst beadsDir = `${process.cwd()}/.beads`;\nconst sandboxOptions = {\n  mounts: [{ hostPath: beadsDir, sandboxPath: beadsDir }],\n  env: { BEADS_DIR: beadsDir },\n};"
