ENV_EXAMPLES = ['# Claude Code OAuth token — get one by running `claude setup-token` on your host.\n# Lets the agent use your Claude subscription instead of an API key.\nCLAUDE_CODE_OAUTH_TOKEN=\n# Or use an Anthropic API key instead — uncomment and fill in:\n# ANTHROPIC_API_KEY=', '# Anthropic API key\nANTHROPIC_API_KEY=', '# OpenAI API key from platform.openai.com (`codex exec` reads CODEX_API_KEY)\nCODEX_API_KEY=', '# Cursor API key (recommended)\n# You can also pass --api-key directly to the agent CLI.\nCURSOR_API_KEY=', '# OpenCode API key\nOPENCODE_API_KEY=', '# GitHub token with the "Copilot Requests" permission\n# (a fine-grained PAT, or any token from `gh auth login`).\n# Copilot CLI reads COPILOT_GITHUB_TOKEN first, then GH_TOKEN, then GITHUB_TOKEN,\n# so this key is used even when GH_TOKEN is set for the issue tracker.\nCOPILOT_GITHUB_TOKEN=', '# GitHub personal access token — the agent uses it to read and manage GitHub Issues\n# Create a fine-grained token: https://github.com/settings/personal-access-tokens/new\n# Required repository permissions: Issues (Read and write) and Metadata (Read)\n# If your prompts have the agent push branches or open pull requests, also grant\n# Contents (Read and write) and Pull requests (Read and write)\nGH_TOKEN=\n# GitHub Enterprise Server hostname, e.g. github.example.com. Leave blank for github.com.\nGH_HOST=\n# GitHub Enterprise Server only: uncomment and put the token here instead of GH_TOKEN\n# GH_ENTERPRISE_TOKEN=']
